select nvl(sum(rd_hours), 0)
from rd_worktime_daily
where project_id    = #{projectId}
  and researcher_id = #{researcherId}
  and to_char(work_date, 'yyyy-MM') = #{monthPrefix}
  and del_flag      = '0'

select nvl(sum(rd_hours), 0)
from rd_worktime_daily
where project_id    = #{projectId}
  and researcher_id = #{researcherId}
  and to_char(work_date, 'yyyy-MM')  <=  #{monthEndInclusive}
  and del_flag      = '0'
